			t.Fatal(err)
		}
		if (<-outcomes).Replay {
			replays++
		}
	}
	if adapter.calls.Load() != 1 || replays != calls-1 {
		t.Fatalf("adapter calls=%d replays=%d", adapter.calls.Load(), replays)
